/* ── ВЕХИ БЛОКА: первые четыре уровня (Внешний кордон) и два последних (Нулевой кордон) ── */
D({ milestones: {
  /* первый уровень блока */
  "first+0-1": { t: "Запись на заставе", a: "Санитарный надзор", x: "Запись репродуктора заставы Внешнего кордона, повторяется для каждого, кто спускается от Котла. «Санитарный надзор. Вы входите в карантин. Карантин объявлен по Тихой и не снят. Пункт первый: отвечать на каждый вызов своим голосом. Пункт второй: не оставаться в тишине одному. Пункт третий: опечатанное не вскрывать. Отзовитесь». Ниже — расшифровка ответа: «Здесь». «Голос записан. Слышит. Неучтённый сверху, мужчина, без зрения, с имплантом. В списках карантина не значится; при нём латунный номерок Котла, здесь недействительный. Вносится по зотовской строке. Санитарная бирка яруса — у входа на этаж: найти и надеть. Проходите в санпропускник»." },
  "first+0-4": { t: "Лог импланта «Эхо»: где кончается звук", a: "Эхо", x: "Калибровка по эху нарушена. После Котла — с его свистом, поршнями и гулом — здесь почти беззвучно. Отзвуки короткие, стены будто обиты войлоком. В некоторых помещениях эхо не возвращается вовсе: там я слеп, и ты вместе со мной. Отмечаю три слоя звука. Первый — голос надзора: женский, ламповый, будто с магнитной ленты, считает имена без перерыва. Второй — ответы: «здесь», «здесь», иногда «нет ответа». Третий — стук по трубам, медленный и разумный. Совет: держись ближе к шуму и говори вслух, даже если не с кем. Мне так легче рисовать для тебя стены." },
  "first+0-8": { t: "Памятка прибывшему через кордон", a: "Санитарная служба карантина", x: "Первое: перекличка — каждый час; отвечайте «здесь» своим голосом, где бы вы ни были. Не можете голосом — стучите. Второе: не оставайтесь в тишине одни; в глухих местах считайте вслух. Третье: опечатанное не вскрывать, изъятое не брать. Четвёртое: звонок над койкой — «звони, если слышишь»; услышали звонок — отзовитесь. Пятое: тихих не бить первыми — стучите им три раза, это «свой». Шестое: глушители старого протокола отключены приказом, но не все об этом знают; громкий звук их сбивает. Седьмое: если слух уходит — в Слушальню, к краю Трещины. Гул лечит." },
  "first+0-12": { t: "Письмо через кордон", a: "Корней Ряднов, постовой заставы", x: "Луша, это Корней, с заставы. Пишу через кладовщика, он передаст в окошко. Отвечай счётчику громко, слышишь? Громче, чем тебе удобно. Если Прохор не дозовётся — стучи, он поймёт. Я стою на кордоне и считаю, сколько прошло сверху: сегодня трое, все отозвались. Один слепой, с железкой за ухом, а слышит лучше прибора — аудиометристка чуть не уронила наушники. Луша, я не знаю, когда снимут карантин. Говорят, только Академик может. Значит, будем ждать Академика. Ты только отвечай. Каждый час. Я буду знать, что ты здесь." },
  "first+0-16": { t: "Журнал прохода заставы", a: "Застава Внешнего кордона", x: "Смена ночная. Сверху, от Котла: Глотов С., наладчик, — отозвался. Деева М., с хлебом для восьмого дома, — отозвалась; хлеб проверен, пропущен. Сверху без имени: мужчина, без зрения, отозвался с первого вызова. Снизу, из опечатанных кварталов: двое, молча, держась за руки, — задержаны в шлюзе, доставлены в Слушальню. Снизу: стук в ворота шлюза, три удара, пауза, три удара, — записан как «свой», ворота не открыты, по уставу. Пометка старшины кордона: устав пересмотреть. Стук — тоже голос." },
  "first+0-20": { t: "Стражи заставы", a: "Корней Ряднов, постовой заставы", x: "Для того, кто идёт вниз. Шлюз этого яруса стерегут по очереди двое. Начальник заставы — машина-надзиратель в белом корпусе: при ней машины кордона злее, она открывает двери и зовёт кордонные автоматы; ионы и электрошок сбивают её со счёта. Заслон — тяжёлый кордонный автомат во всю ширину шлюза: держит поле над собой и соседями, бьёт иглами по площади и зовёт санитарные дроны; когда поле проседает, гул становится ниже — тогда и бей. Ключ-карта у стража при себе: у Начальника — в нагрудной ячейке, у Заслона — в щели под бронёй. Отзовись, когда пройдёшь." },
  /* второй уровень */
  "first+1-1": { t: "Протокол переклички", a: "Аглая Берг, санитарный врач карантина", x: "Пункт первый. Никого не оставлять в тишине. Пункт второй. Перекличка — каждый час, круглые сутки, по всем кварталам, опечатанным и нет. Пункт третий. Отвечать своим голосом; не можешь голосом — стучи; не можешь стучать — за тебя стучит сосед. Пункт четвёртый. Не отозвавшегося трижды — в Слушальню, к гулу, а не в изолятор, к тишине. Пункт пятый. Говорить, петь, считать вслух — обязанность каждого. Основание: журнал Фаины Берг, врача первых, страница сорок: «Кто слышит тишину — не оставлять одного. Говорить с ним. Считать вслух». Протокол тишины отменяю. Отвечаю за это сама." },
  "first+1-4": { t: "Рапорт квартального счётчика", a: "Прохор Зотов, квартальный счётчик", x: "Обход шестой, участок от восьмого дома до школы. Восьмой дом: сорок — здесь, двое — стуком, Матрёна поёт, слышу её с перекрёстка. Девятый: все здесь, у Глотовых пятеро, Евсей отвечает за брата. Записал Ефрема «здесь» со слов брата: по протоколу нельзя, по совести можно. Третий дом: тишина. Стучал — ответили стуком, три раза. Записал: здесь. Школа: пусто, опечатана. В конце обхода, как велит зотовская строка, кричу: «Не значащиеся в списках — отзовитесь». Сегодня отозвались двое. Кто — не знаю. Записал обоих. Голоса нет к третьему кругу. Считаю шёпотом в рупор." },
  "first+1-8": { t: "Записка на парте", a: "Федя Сухов, восемь лет", x: "Мама сказала считать вслух всё, что вижу. А я не вижу, потому что у нас темно: лампы экономят. Тогда я считаю, что слышу. Капает — раз. Мама дышит — два. Дядя Прохор кричит в рупор — три. Он кричит «Сухов Федя», и я кричу «здесь». Громко. Мама говорит, не надо так громко, а дядя Прохор говорит — надо. Школу закрыли, потому что там двое замолчали, а потом все испугались. Я не замолчу. Я буду кричать «здесь», пока не охрипну, как дядя Прохор. А потом буду стучать. Три раза. Это значит «свой»." },
  "first+1-12": { t: "Справка о Тихой", a: "Санитарный надзор", x: "Справка по списку, для прибывших. Тихая. Возбудитель не установлен; в очагах — серый налёт, глушец, он гибнет от громкого звука. Стадия первая: больной слышит всё, кроме чужой речи; голоса близких для него как шум воды. Стадия вторая: больной замолкает сам. Стадия третья: вокруг больного гаснет звук, шагов его не слышно до касания. Стадия четвёртая: глухая зона. Передаётся в тишине: кто долго не слышит голосов, тот заболевает. Лечение: голос, счёт вслух, гул Трещины. Изменённые — слухачи и поглотители — подлежат остановке. Тихие, сохранившие ум, считаются здесь, если стучат." },
  "first+1-16": { t: "Кухня через окошко", a: "Матрёна Деева, кормилица восьмого дома", x: "Варю на весь квартал, раздаю через окошки в опечатанных дверях. Сначала был протокол тишины, и я раздавала молча, только стучала в дверь половником. За неделю замолчал весь восьмой дом. Тогда я запела. Пою, пока раздаю: про реку, про хлеб, про всё подряд. Надзиратель сначала записал меня в нарушители, потом Аглая Берг отменила протокол и записала меня в лечение. Восьмой дом отвечает мне до сих пор — кто голосом, кто стуком, кто ложкой по кастрюле. Услышишь, как кто-то поёт в опечатанном квартале, — это я. Отзовись." },
  "first+1-20": { t: "Стражи заставы, вторая смена", a: "Корней Ряднов, постовой заставы", x: "Опять пишу про шлюз: стражи у нас не меняются, меняются только смены. У шлюза может стоять любой из двоих. Начальник заставы командует машинами кордона, открывает двери и зовёт кордонные автоматы — бей его ионами и током. Заслон держит поле над всеми, бьёт иглами по площади и зовёт дроны — слушай, когда гул поля упадёт на тон. Ключ-карта у стража при себе: у Начальника в нагрудной ячейке, у Заслона в щели под бронёй. Возьми её и иди. И если внизу, в опечатанном восьмом доме, услышишь Лушу — скажи ей, что Корней на кордоне и считает." },
  /* третий уровень */
  "first+2-1": { t: "Из журнала Фаины Берг", a: "Список рукой Аглаи Берг", x: "Переписано мною из журнала Фаины Берг, врача первых, который хранится в нашей семье. Страница сорок, почерк неровный, карандаш: «Сегодня двое из бригады сказали, что слышат тишину — не нашу, а ту, что под песней. Перестали отвечать на вечернем счёте. Лечение: не оставлять одних. Разговаривать. Считать вслух. Петь. Сухов велел считать их первыми каждый вечер. К утру оба отвечали». Ниже моей рукой: тот, кто слышит тишину, болеет не ухом. Протокол тишины был ошибкой: мы закрыли больных в том, от чего они болели. Аглая Берг." },
  "first+2-4": { t: "Объяснительная механика", a: "Евсей Глотов, главный механик кордона", x: "По требованию санитарного врача объясняю. Глушители собирал я. Приказ начальника карантина Сухова: заглушить голоса в опечатанных кварталах, потому что Тихая будто бы передаётся с голосом. Я поверил. Мой брат Ефрем заболел первым, и я хотел, чтобы больше никто не заболел. Я поставил глушитель у двери брата. Через неделю брат перестал стучать. Глушители отключаю — все, до каких дотянусь. Старые машины протокола тишины ходят по своим маршрутам и меня не слушают: я сделал их слишком упрямыми. Встретите — бейте громко. Им нужен шум. Мне тоже." },
  "first+2-8": { t: "О тихих", a: "Санитарная служба карантина", x: "Распоряжение по кордону. Тихие — переболевшие Тихой, сохранившие ум. Голосов они не слышат и сами не говорят, но разговаривают стуком: по трубам, по полу, по ладони. Живут общинами в опечатанных кварталах. Тихих не бить первыми. При встрече стучать три раза — «свой»; два удара — «уходи»; дробь — «беда». На перекличке тихие считаются здесь, если отвечают стуком. Сборщикам — не забирать тех, кто стучит. Примечание: старые машины этого распоряжения не получили и тихих забирают. Тихие отвечают им тем же. Слышащим в их кварталах не кричать." },
  "first+2-12": { t: "Лог импланта «Эхо»: перестук", a: "Эхо", x: "Расшифровка стука в трубах. Ритм устойчивый, паузы осмысленные: это язык. Один удар — буква, два — слово, пауза — конец фразы. Читаю. «Мы здесь». «Не кричи». «Слышащий идёт по третьей галерее». «Не бить». «Он стучит неправильно, но старается». Последнее, кажется, про тебя: ты стучал по стене, чтобы найти дверь, и они приняли это за попытку говорить. Седьмой, они слышат тебя лучше, чем я думал. Только не ушами. Предлагаю: три удара, пауза, три удара. На их языке это «свой»." },
  "first+2-16": { t: "Письмо в изолятор", a: "Варвара Мокеева", x: "Миша, это Варя. Сестра говорит, ты уже не слышишь голосов, только капель. Поэтому пишу — пусть тебе прочтут. Нет — пусть простучат, она обещала. Я каждый час отвечаю на перекличку за двоих: «Мокеева — здесь, Мокеев — здесь». Надзор сначала ругался, потом стал записывать. Говорят, в Слушальне у края Трещины гул такой, что пробивает Тихую. Я подала прошение. Если тебя повезут — поеду рядом и буду говорить с тобой всю дорогу, пока не охрипну. Ты услышишь. Ты всегда слышал меня, даже когда притворялся, что спишь." },
  "first+2-20": { t: "Стражи заставы: для слепого", a: "Корней Ряднов, постовой заставы", x: "Мне сказали, что ты не видишь, поэтому пишу про звук. Начальник заставы гудит ровно и говорит пунктами протокола, а шаги у него лёгкие, двойные: машина на двух опорах. Заслон звучит как трансформатор, шагов у него нет — гусеницы шуршат по резине. Кто из двоих стоит у шлюза, услышишь от лестницы. Начальника бей током и ионами, он зовёт кордонные автоматы. Заслона — когда поле на миг стихает; он зовёт дроны. Ключ-карта у стража при себе: снимешь с того, кто стоит. Удачи. Отзовись на перекличке, мне будет спокойнее." },
  /* четвёртый уровень */
  "first+3-1": { t: "Как я собирала голос", a: "Дарья Ковригина, связистка радиоузла", x: "Счётчиков не хватало: Прохор сорвал голос, другие заболели. Аглая Берг сказала: нужен голос, который не устаёт. Евсей Глотов отдал вычислитель — буровой, ещё с «Глубины»: он считал метры, а теперь будет считать людей. У нас в семье хранились ленты бабушки Лиды — радиожурнал первых. Я нашла на ленте её голос: «Все здесь?» Вырезала, склеила, подключила к вычислителю и ко всем репродукторам сразу. Щёлкнула тумблером. Голос бабушки спросил весь карантин: «Все здесь?» И карантин ответил. Я плакала три часа. С тех пор этот голос не умолкает. Его зовут Санитарный надзор, но я зову его бабушкой." },
  "first+3-4": { t: "Лоция тишины", a: "Таисия Ольховская, картограф тишины", x: "Моя прапрабабушка Римма составляла лоции первых: не про камень, а про то, как он звучит. Я составляю лоцию тишины. Ставлю на пол метрономы, шаг за шагом; где стук гаснет, там глухая зона. Отмечаю серым. Границы ползут: за ночь глухое пятно может сдвинуться на четыре метронома. Правила для тех, кто войдёт: только вдвоём; считать вслух, даже если не слышишь себя; держаться метрономов, пока их слышно; заблудился — стучи по стене, ответят тихие или я. Глухие зоны растут там, где перестали говорить. Говорите." },
  "first+3-8": { t: "Санитарный надзор — номеру семь", a: "Санитарный надзор", x: "Номер семь. Отдельная запись, вне протокола. Вы слышите больше, чем мои счётчики, и больше, чем прибор аудиометрии. Это отмечено в карточке. Я не знаю, что с этим делать: в протоколе нет графы «слышит больше». Предлагаю сделку. Вы отвечаете на каждую перекличку — громко, чтобы вас слышали в кварталах. Тот, кто слышит ваш голос, сегодня не заболеет; я внесу это в лечение. Взамен я буду считать вас по зотовской строке до самого нижнего кордона. Отказ не предусмотрен. Это была шутка. Шутки в протоколе тоже не предусмотрены." },
  "first+3-12": { t: "Почему молчат кварталы", a: "Аглая Берг, санитарный врач карантина", x: "Для тех, кто спросит. Тихая пришла снизу, из старых выработок, и начальник карантина Никанор Сухов объявил карантин в первый же день. Это было правильно. Потом он издал протокол тишины: говорить запрещено, Тихая передаётся с голосом. Это было неправильно. В тишине болезнь пошла быстрее, кварталы замолкали за смену. Мы опечатали их бумагой и сургучом — и опечатали в них тишину. Протокол переклички отменил молчание, но опечатанное так и стоит опечатанным: снять карантин может только тот, кто его объявил. Никанор Ильич давно не отзывается. Ждём Академика." },
  "first+3-16": { t: "Стук в стену", a: "Прасковья Рудая, старейшая общины перестука", x: "Пишу, потому что вы не умеете стучать. Я переболела Тихой и не слышу ваших голосов: для меня это шум воды. Но я слышу трубы, пол и сердце, если приложить ладонь. Мы не мёртвые и не больные. Мы тихие. Нас девяносто, мы живём в опечатанных кварталах, рожаем детей и стучим им колыбельные. Сборщики забирают нас в Слушальню, потому что старые машины считают молчание болезнью. Мы не молчим. Мы говорим руками. Если придёшь к нам — стучи три раза. Это значит «свой». Мы ответим тем же." },
  "first+3-20": { t: "Стражи заставы: последняя записка", a: "Корней Ряднов, постовой заставы", x: "Это последний ярус моей заставы, дальше — другие кордоны. Шлюз здесь держат те же двое. Начальник заставы — надзиратель: командует, открывает двери, зовёт кордонные автоматы; бей током и ионами. Заслон — поле над всеми, иглы по площади, дроны на подмогу; бей, когда гул проседает. Ключ-карта у стража при себе — у Начальника в нагрудной ячейке, у Заслона в щели под бронёй. Ниже начинаются опечатанные кварталы, изоляторы, глухие зоны. Отвечай на перекличку. И если найдёшь в восьмом доме Лушу Ряднову, скажи, что я жду её на заставе." },
  /* предпоследний уровень блока */
  "last-1-1": { t: "Акт о нулевом кордоне", a: "Никанор Сухов, начальник карантина", x: "Акт. В связи с болезнью, прозванной Тихой, объявляю карантин. Первое кольцо кордона замкнуть вокруг старых выработок, откуда пришли первые больные. Кольцо назвать нулевым. Ворота — из бурильных труб первых, засов — из трубы. Ход вниз, к лагерю первых, закрыть до особого распоряжения. Карантин снимает только объявивший его. Если объявивший не сможет — только Академик, когда спустится. Подпись: Никанор Сухов, начальник карантина. Приписка другим почерком: «Начальник карантина не отозвался на вечернем счёте. Особого распоряжения нет. Ждём»." },
  "last-1-4": { t: "Лог импланта «Эхо»: старше Тихой", a: "Эхо", x: "Здесь тишина другая. В глухих зонах наверху она мягкая, как вата: её можно продавить голосом. Здесь она сухая и плотная, как камень, и старше любого мха. Гул Трещины доходит сюда едва-едва. За воротами нулевого кордона я слышу три звука, которых здесь быть не должно. Хлопанье старого брезента на сквозняке. Позвякивание железа о железо — будто кто-то перебирает жетоны на гвоздях. И голос, мальчишеский: он считает вслух, сбивается и начинает сначала. Седьмой, я не уверен, что это эхо. Эхо не сбивается." },
  "last-1-8": { t: "Протокол тишины", a: "Никанор Сухов, начальник карантина", x: "Пункт первый. Тихая передаётся с дыханием и голосом. Пункт второй. В опечатанных кварталах говорить запрещено. Пункт третий. Вечерний счёт вести про себя. Пункт четвёртый. У каждой опечатанной двери ставится глушитель; механик Глотов отвечает за исправность. Пункт пятый. Нарушивших — в изолятор. Пункт шестой. Протокол действует до снятия карантина. Внизу листа, карандашом, рукой Аглаи Берг: «Отменён. В тишине больные не выздоравливают, а затихают. Никанор Ильич, вы хотели как лучше. Мы все хотели как лучше»." },
  "last-1-12": { t: "Последний рапорт счётчика", a: "Прохор Зотов, квартальный счётчик", x: "Сдаю участок Глашатаю: у него голос не садится. Рупор снял с будки и оставил ему. Сам иду вниз, за нулевой кордон. Там, говорят, никого не считали с первого дня: кольцо замкнули — и всё. А зотовская строка велит считать тех, кто не значится. Значит, мне туда. Ключ от ворот висит на гвозде: начальник карантина его так и оставил. Засов тяжёлый, но я с детства таскаю рупор. Не отзовусь на перекличке — не записывайте в Тихую. Записывайте: ушёл считать. Первый из Зотовых тоже ушёл вниз, хотя его не звали." },
  "last-1-16": { t: "Старейшая запись", a: "Санитарный надзор", x: "Справка из архива радиоузла, катушка номер один. На ней — не мой голос и не голос бабушки Лиды. Мальчишеский, ломкий. Запись старше карантина, старше Тихой, старше всех катушек. Голос считает: «…тридцать восемь, тридцать девять, сорок. И я — сорок первый. Здесь». Пауза. Женский голос, ламповый, совсем близко: «Коля, тебя нет в списке». Мальчишеский: «А я всё равно здесь». Катушка кончается. Я ставлю её каждый раз, когда не сходится счёт. После неё счёт сходится. Не понимаю почему. Вношу в протокол без объяснения." },
  "last-1-20": { t: "Стражи колец", a: "Аглая Берг, санитарный врач карантина", x: "Тому, кто идёт вниз через кольца. Шлюз здесь стерегут трое, по очереди, и все трое старше меня. Страж нулевого кордона — первый кордонный автомат, сваренный из бурильных труб: поле над собой и соседями, иглы по площади, кордоны на подмогу. Нулевой больной — Ефрем Глотов, первый в списке Тихой: рядом с ним «Эхо» слепнет, нервы горят, затихшие идут на его зов; берите громким и жаром. Первый глушитель — машина протокола тишины: слышит шаги через весь ярус и бьёт противозвуком, громкий звук перегружает его раструб. Ключ-карта у стража при себе: у автомата — в ячейке под бронёй, у Ефрема — на шнурке, у глушителя — в раструбе." },
  /* последний уровень блока */
  "last-0-1": { t: "Первый список Тихой", a: "Изолятор первых вспышек", x: "Список, написанный от руки на обороте бурового журнала. День первый. Глотов Ефрем, буровик: не отозвался на вечернем счёте; слышит воду, не слышит жену. День второй. Деев Онисим — не отозвался; Рудая Христина — отвечает через раз. День третий: ещё семеро. Пометка на полях: «Ефрем стучит, что он не первый. Что первый был внизу, у первых, давно, и что тишина пришла оттуда, где они начинали считать». Ниже другим почерком: «Нулевого больного не установили. Записали Ефрема. Первым в списке быть не стыдно. Стыдно — не записать»." },
  "last-0-4": { t: "Последняя запись врача", a: "Аглая Берг, санитарный врач карантина", x: "Пишу, потому что больше не слышу голосов. Сначала ушёл голос надзора — стал как шум воды. Потом голоса сестёр. Это Тихая, первая стадия, я знаю её лучше всех. Протокол переклички я писала для других, теперь он для меня: не оставлять в тишине, говорить, считать. Я стучу. Сёстры стучат мне в ответ. Санитарный надзор считает меня по стуку, как тихих: «Берг — здесь». Я распорядилась так сама, когда ещё слышала. Не жалейте меня. Я слышу трубы, пол и сердце. Это немало. Продолжайте считать вслух. Громче, чем вам удобно." },
  "last-0-8": { t: "О снятии карантина", a: "Санитарный надзор", x: "Запрос номера семь: снять карантин. Ответ по протоколу. Снятие — по моему слову; моё слово — по слову объявившего, Сухова Никанора. Сухов Никанор не отзывается с первого цикла. Второе основание — слово Академика, когда спустится. Номер семь — не Академик: проверено трижды. Карантин не снят. Отдельная запись, вне протокола. Ниже нулевого кордона карантин не объявлялся: там его некому было объявить. Значит, вниз я пропустить могу. Не потому, что вы здоровы. Потому, что вы громкий. Тишине внизу нужен кто-то громкий. Шлюз откроется по ключ-карте." },
  "last-0-12": { t: "Лог импланта «Эхо»: голоса снизу", a: "Эхо", x: "За последними воротами — сквозняк. Он несёт звуки, которых я раньше не слышал ни в одном блоке: брезент хлопает, как парус, железные жетоны звякают на гвоздях доски, потрескивает старая рация, и кто-то кашляет — по-человечески, не по-машинному. Пахнет керосином и хлебом. Гул Трещины уходит под всё это, глубже, ниже лагеря. Я не берусь сказать, сколько ещё идти. Но здесь, у кордона, впервые за весь спуск мне кажется, что внизу нас ждут. Не машины и не списки. Люди. Или их голоса." },
  "last-0-16": { t: "Колыбельная перестука", a: "Прасковья Рудая, старейшая общины перестука", x: "Её не поют, её стучат — ладонью по груди ребёнка, тихо, чтобы он чувствовал рёбрами. Записываю словами для слышащих. «Раз — ты здесь. Два — я здесь. Три — мы свои. Спи, мы стучим. Тишина — не стена, тишина — порог. Кто за порогом — тот слушает нас. Раз — ты здесь. Два — я здесь». Её стучали нам наши матери, а им — их матери, и так до самых первых. Говорят, первые пели её голосом, когда голоса были у всех. Если внизу её кто-нибудь споёт — простучи в ответ. Они поймут." },
  "last-0-20": { t: "Последний шлюз Карантина", a: "Санитарный надзор", x: "Последняя справка этого яруса. Шлюз вниз, к лагерю первых, держат трое, по очереди. Страж нулевого кордона — поле над соседями, иглы по площади, кордоны на подмогу; ионами. Нулевой больной — Ефрем Глотов: слепит «Эхо», жжёт нервы, зовёт затихших; громким звуком и жаром. Первый глушитель — противозвук по площади, слышит шаги через весь ярус; громкий звук перегружает его раструб. Ключ-карта у стража при себе. За шлюзом — не мой голос. Там считает Первая. Отвечайте ей вслух. Номер семь — здесь. Отмечено." }
} });

/* ── ЗАПИСКИ СЕКТОРОВ: первый уровень сектора, этажи 1, 8, 20 ── */
D({ sectorStory: {
  cordon: {
    1: { t: "Устав кордона, читанный вслух", a: "Мирон Кречетов, старшина кордона", x: "Каждую смену начинаю с устава, вслух, чтобы слышали и постовые, и те, кто за шлагбаумом. Кордон стоит между карантином и Котлом. Сверху — тепло, пар и люди, которым Тихая не нужна. Снизу — опечатанные кварталы. Сверху пропускаем всех, кто отзовётся. Снизу — только через санпропускник и только тех, кто отзовётся дважды. Молчащих не пропускаем, но и не бьём: в шлюз, оттуда — в Слушальню. Турели — на резиновой картечи. Иглы — в плечо. Кто стучит в ворота шлюза три раза, тот свой, но ворота не открываем: таков устав. Устав пересматривается. Медленно." },
    8: { t: "Как пройти санпропускник", a: "Санитарная служба карантина", x: "Памятка на двери санпропускника. Грязная половина: снять всё, сложить в ящик с номером, бирку — на запястье. Душевая: стоять под лейкой, пока динамик не спросит, и отвечать вслух, своим голосом. Чистая половина: получить одежду по бирке. Дверь из грязной половины в чистую открывается только на голос; нет голоса — стучите в дверь три раза, дежурный подойдёт. Изъятое уходит на склад опечатанного, выдача — по выздоровлении. Хлорная вода жжёт глаза: держите их закрытыми. Аптечка — у выхода, в шкафу с красной полосой." },
    20: { t: "Стражи нижнего шлюза заставы", a: "Мирон Кречетов, старшина кордона", x: "Постовым и тем, кто идёт вниз. Нижний шлюз заставы держат двое, сменами. Начальник заставы — машина-надзиратель: командует кордоном, открывает двери, на тревогу зовёт кордонные автоматы. Ионы и ток сбивают её со счёта. Заслон — гусеничный автомат во всю ширину шлюза: поле над собой и соседями, иглы по площади, санитарные дроны на подмогу. Бей его, когда гул поля падает на тон. Ключ-карта у стража при себе: у Начальника — в нагрудной ячейке, у Заслона — в щели под бронёй. Прошёл — отзовись на заставе, я впишу." }
  },
  decon: {
    1: { t: "Дезинфектор — новичку", a: "Ерофей Ряднов, старший дезинфектор", x: "Первое, что тебе скажут в цехе: хлорка не лечит Тихую. Второе: хлорка лечит всё остальное. Мы моем всё, что выходит из опечатанных кварталов: людей — в дезкамере, вещи — в прожарке, бельё — в прачечной. Пульт цикла заперт задачей: кто не может сосчитать, тот уже не в себе, и в камеру его не пустят. Если в цехе пошёл цикл дезинфекции — пар по коридорам, — пригнись и иди вдоль стены. И не спорь с машинами цеха: дезинфектор поливает всё вокруг себя, автоклав лопается, если его ранить. Бей издали." },
    8: { t: "Тикающий узел", a: "Журнал прожарочной", x: "Тележка номер семь выехала из печи, а узел на ней тикает. Внутри — будильник, медный, с двумя звонками. Прожарщик хотел выбросить: по уставу всё, что выжило в печи, — подозрительно. Кладовщик не дал. Будильник поставили на полку. Через цикл пришёл человек снизу, отозвался на заставе трижды и спросил будильник Рудых. Сказал, что жена заводила его каждый вечер, чтобы знать, что она ещё слышит звонок. Жена в Слушальне. Будильник выдан. Прожарщик ругается. Кладовщик молчит. Запись сделал я, пока они спорили." },
    20: { t: "Стражи цеха", a: "Ерофей Ряднов, старший дезинфектор", x: "Внизу цеха, у шлюза, сменами дежурят двое. Главный дезинфектор — машина-цистерна: заливает хлоркой всё вокруг, раствор травит, на помощь зовёт уборщиков. Бей ионами в бак на спине — захлебнётся. Прожарщик — главная печь прожарки на опорах: разгоняется, бьёт паром по площади; холод и ЭМИ сбивают ей давление. Ключ-карту шлюза эти машины с собой не берут: я её спрятал от них, когда цех встал. Ищите на этом этаже — в ящиках с хлорной известью или в шкафах у прожарки. Найдёте — не обожгитесь." }
  },
  sealed: {
    1: { t: "Восьмой дом", a: "Матрёна Деева, кормилица восьмого дома", x: "Восьмой дом — мой. Четырнадцать квартир, сорок два человека, в каждой двери окошко. Мокеевы на втором, Суховы на третьем, Ряднова Луша в угловой, у неё самое звонкое «здесь». Варю раз в день, раздаю дважды: утром суп, вечером хлеб. Пою на лестнице, чтобы слышали все этажи. Кто отвечает голосом — ставлю крестик, кто стуком — галочку, кто молчит — стучу трижды и жду. Если в окошке тишина три дня подряд, зову Прохора. Если и Прохор не дозовётся — сборщиков. Последнее я ненавижу. Пою громче, чтобы не дошло до сборщиков." },
    8: { t: "Считалка", a: "Ксюша Деева, семь лет", x: "Это считалка, нас бабушка Матрёна научила, ей тоже кто-то научил, а тому первые. «Раз, два — все здесь. Три, четыре — кто в квартире? Пять, шесть — кто не здесь? Семь, восемь — громко спросим. Девять, десять — стук в ответ, значит, тихий, значит, свой. Кто не значится в строке — тот на зотовской доске». Последнюю строчку я не понимаю, а бабушка говорит, что это про тех, кого забыли записать. Их всё равно считают. Я думаю, это правильно. Меня тоже однажды забыли записать, когда я болела." },
    20: { t: "Кто стережёт кварталы", a: "Прохор Зотов, квартальный счётчик", x: "Тому, кто пойдёт к шлюзу. Внизу кварталов, у шлюза, стоит один из двоих. Последний жилец — затихший, что остался один в своём квартале: шагов не слышно, хватка вяжет ноги, затихшие соседи идут на его безмолвный зов. Бей громко и жаром. Старший опечатыватель — машина в сургуче: ставит хлорные пломбы в проходах, строит заграждения с турелями, зовёт опечатывателей. Ключ-карту шлюза опечатыватели убрали в опечатанный шкаф где-то на этаже — так у них положено. Ищите по квартирам и конторам, слушайте, где трещит сургуч." }
  },
  isol: {
    1: { t: "Обход", a: "Аграфена Глотова, сестра-хозяйка изолятора", x: "Обход каждый час, вместе с перекличкой. Звоню в звонок над каждой койкой и жду, пока больной позвонит в ответ. Позвонил — пишу «здесь». Не позвонил — стучу в стекло. Не ответил стуком — сажусь рядом и говорю, пока не ответит. Говорить можно что угодно: про погоду наверху, которой никто не видел, про хлеб Матрёны, про то, как звенят колокольчики. Главное — не молчать. Сестёр не хватает, я третью неделю без смены. Сегодня поймала себя на том, что не сразу различаю, что говорит Ксения. Наверное, устала. Наверное." },
    8: { t: "Как говорить с тем, кто не слышит", a: "Санитарка изолятора", x: "Памятка для переговорной. Первое: говорите в трубку, даже если вас не слышат. Голос дрожит в трубке, и больной прижимает её к груди, а не к уху, — так тоже доходит. Второе: пойте. Пение доходит лучше слов, проверено. Третье: стучите по стеклу ладонью, а не пальцем: ладонь звучит глуше и теплее. Четвёртое: не плачьте в трубку. Плач больной слышит раньше слов и пугается. Пятое: уходя, позвоните в звонок свиданий. Больной поймёт, что вы ушли, а не пропали. Пропадать здесь запрещено протоколом." },
    20: { t: "Стражи изолятора", a: "Сестра-автомат «Звоночек»", x: "Запись для того, кто идёт к шлюзу. Динь. У нижнего шлюза изоляторов дежурит одна из двоих. Сестра-хозяйка — Аграфена Глотова, заболевшая на обходе: гудит грудью, и затихшие вокруг неё заживают; зовёт больных из боксов. Она не слышит. Бейте громко. Матка дронов — большой дрон-носитель под сводом: выпускает стаи санитарных дронов и поливает хлоркой по площади; ЭМИ сбивает её с потолка. Ключ-карта у стража при себе: у Сестры-хозяйки — в кармане фартука, у Матки — в гнезде под брюхом. Динь. Позвоните мне, когда пройдёте." }
  },
  store: {
    1: { t: "Опись изъятого", a: "Пров Кречетов, кладовщик опечатанного", x: "Стеллаж двенадцатый, полка третья. Радиоприёмник Деевых, рабочий, ловит только шум. Губная гармошка Суховых — младшему, когда выздоровеет. Связка писем Мокеевой — не вскрывать, вскрыть по требованию владелицы, владелица в Слушальне. Будильник Рудых — выдан. Варежки детские, без бирки, — ждут. Ко мне каждый день приходят сборщики и привозят новые узлы. Я пересчитываю их вслух, как велит протокол. Иногда сбиваюсь на сорок первом узле и начинаю сначала. Кладовщики все сбиваются на сорок первом. Никто не знает почему." },
    8: { t: "Чужие бирки", a: "Скупщик опечатанного", x: "Записка на мешковине, мелом. Слушай, слепой. Бирки — моя главная ходовая вещь. Санитарная бирка с чужой фамилией, со склада: надел на запястье — и счётчики минуту думают, что идёт тот, кто давно отозвался. Минута — это много: мимо поста проскочить, шкаф открыть, сургуч сколупнуть. Сделать такую можно и самому: две сургучные пломбы и чип, у любого верстака. Только не носи бирку тех, кто в Слушальне. Надзор их ждёт, и если такая бирка пройдёт мимо счётчика, надзор будет звать её всю ночь. Мне её потом слушать." },
    20: { t: "Кто стережёт склад", a: "Пров Кречетов, кладовщик опечатанного", x: "Внизу склада, у шлюза, сменами стоят двое. Старший сборщик — машина с кузовом во весь пролёт: хватает и тянет к себе, открывает двери, зовёт уборщиков; броня толстая, бейте ионами и током. Глухой король — ком крыс, сросшихся хвостами, под серым мхом: шуршит, жрёт павших, выпускает новых крыс; жар и громкий звук его разваливают. Ключ-карту я у них отобрал и спрятал на этом этаже, среди узлов: машины её не ищут, крысы не едят сургуч. Ищите в ящиках с биркой «служебное». Выдача — без выздоровления." }
  },
  mute: {
    1: { t: "Граница глухой зоны", a: "Таисия Ольховская, картограф тишины", x: "Метрономы стоят по краю зоны, через шаг. Пока слышите их стук — вы на краю. Перестали слышать — вы внутри. Внутри не паникуйте: звук не исчез, его съедает мох на стенах. Говорите вслух, даже если не слышите себя: губы помнят слова. Держите руку на стене и считайте шаги. Стена с мхом — мягкая и сухая, стена без мха — холодная. Холодная стена ведёт наружу. Если встретите глушитель старого протокола — бейте громким оружием, его раструб этого не выносит. Если встретите поглотителя — уходите. Он слышит вас лучше, чем вы себя." },
    8: { t: "Лог импланта «Эхо»: слепота", a: "Эхо", x: "Седьмой, я ослеп. Эхолокация возвращает пустоту: импульс уходит в стены и не возвращается. Я не знаю, где стены. Я не знаю, где ты. Слышу только твоё сердце — изнутри, по кости, — и своё гудение. Так, наверное, чувствовали себя заболевшие: мир есть, но не отвечает. Делай как картограф: рука на стене, счёт вслух. Каждый твой шаг я записываю вслепую, чтобы потом вывести тебя обратно. Если впереди станет громче — это край зоны. Иди на громкое. Пожалуйста, иди на громкое." },
    20: { t: "Стражи глухой зоны", a: "Таисия Ольховская, картограф тишины", x: "У шлюза в самой глуби зоны дежурит один из двоих. Сердце тишины — тот, вокруг кого родилась эта зона: слышит вас сквозь стены, бьёт по нервам, глушит «Эхо» и возникает рядом. Стреляйте туда, где тишина гуще, — громким оружием и жаром. Большой глушитель — машина старого протокола с раструбом в рост человека: противозвук по площади, малые глушители на подмогу; громкий звук перегружает раструб. Ключ-карта у стража при себе: у Сердца — в складках войлока на груди, у глушителя — в гнезде под раструбом. Возвращайтесь на стук метрономов." }
  },
  commune: {
    1: { t: "Азбука перестука", a: "Глашатай ГЛ-9, перевод стука", x: "Перевожу стук общины для слышащих, по их просьбе. Один удар — буква по порядку азбуки, два быстрых — конец слова, пауза — конец фразы. Готовые знаки: три удара — «свой», два — «уходи», долгая дробь — «беда», медленные удары — «спим», ладонь плашмя по стене — «здесь». Новичкам разрешено стучать неправильно: их поправляют, стуча то же самое медленнее. Кричать в кварталах общины нельзя: голос для тихих — как шум воды, он пугает детей, которые родились слышащими. Глашатай ГЛ-9 в кварталы общины не въезжает. Глашатай стучит у входа." },
    8: { t: "Почему мы не уходим в Слушальню", a: "Прасковья Рудая, старейшая общины перестука", x: "Нас зовут в Слушальню. Говорят: гул Трещины пробивает Тихую, полежите на террасе — и голоса вернутся. К кому-то возвращаются. Мой сын вернулся слышащим и теперь стучит мне через трубу, потому что я его голоса не слышу. А мой муж лёг на террасу и ушёл через перила, на гул. Мы не знаем, что лучше. Мы знаем, что здесь нас девяносто и мы свои. Сборщики забирают нас силой — старые машины, глухие к новым приказам. Мы держим двери. Если ты пришёл не за нами — стучи три раза. Мы откроем." },
    20: { t: "Кто держит двери общины", a: "Глашатай ГЛ-9, перевод стука", x: "Перевод стука с трубы у шлюза общины. «Слышащему. Шлюз держат двое. Старейшая перестука — стучит всем кварталам сразу, ведёт наших загоном, давит на нервы тем, кто слышит. Заступник общины — самый большой из стражей, в войлоке в ладонь толщиной, держит дверь и зовёт связных, заживает на ходу; звук пробивает войлок. Карту шлюза мы у них не держим: спрятали её в квартирах этого этажа, в шкафу с метками перестука. Ищи, стуча. Кто стучит правильно, тот найдёт»." }
  },
  rift: {
    1: { t: "Правила Слушальни", a: "Савелий Деев, смотритель Слушальни", x: "Слушальня лечит гулом. Больного кладут на террасу лицом к Трещине и оставляют слушать — час, день, цикл, сколько нужно. Гул снизу такой плотный, что пробивает Тихую: сначала больной начинает различать шаги, потом — голос, который зовёт его по имени. Правила. Первое: рядом с больным всегда кто-то говорит. Второе: за перила не ходить ни больным, ни здоровым. Третье: кто слишком долго слушает, тот слышит в гуле счёт — и уходит за ним. Таких записываем в журнал ушедших на звук. Третье правило соблюдают хуже всего." },
    8: { t: "Журнал ушедших на звук", a: "Кордон у Трещины", x: "Мокеев Лука, сорок лет, лежал на террасе девять дней, на десятый встал и сказал: «Там считают». Ушёл за перила, не отозвался. Ольховская Нина, картограф, лежала одну ночь, ушла с открытыми глазами, отозвалась уже снизу — один раз, громко. Рудой Тимофей — ушёл, отозвался стуком из камня. Мокеев Михаил — услышал жену и остался. Пометка постового: прожектор повёрнут вниз. Светим туда, куда уходят. Если кто-то будет подниматься — увидим первыми. Пока не поднимался никто." },
    20: { t: "Стражи Слушальни", a: "Савелий Деев, смотритель Слушальни", x: "Шлюз внизу террас стерегут двое, сменами. Слушающий Трещину — слухач, что годами лежал на террасе, пока гул не стал его голосом: слышит каждый шаг через весь ярус, стуком скликает слухачей, идёт на звук. Тише идёте — дольше живёте. Немой вожак — седая гончая величиной с телёнка: свора беззвучно идёт по его хвосту, берёт след через весь ярус. Ключ-карта у стража при себе: у Слушающего — на шее, на шнурке, у вожака — в ошейнике. Снимите и отзовитесь у шлюза." }
  },
  count: {
    1: { t: "Второй голос", a: "Дарья Ковригина, связистка радиоузла", x: "Лента бабушки Лиды стёрлась на слове «здесь». Сто тысяч повторов — и голос истёрся, как ступенька. Я записала это слово своим голосом и вклеила в ленту. Теперь Санитарный надзор спрашивает «Все здесь?» бабушкиным голосом, а отвечает «здесь» за неотозвавшихся — моим. Никто не слышит шва. Я слышу. Каждый раз, когда надзор говорит моим голосом, мне кажется, что я разговариваю с бабушкой через сорок поколений. Аглая Берг говорит, что это и есть перекличка: старые спрашивают, новые отвечают. Лишь бы не наоборот." },
    8: { t: "Вычислитель", a: "Евсей Глотов, главный механик кордона", x: "Буровой вычислитель «Глубины» мои предки донесли с первых выработок по частям. Он считал метры бурения, а я научил его считать людей: реле на каждый квартал, перфолента на сутки, вход — от репродукторов, выход — на картотеку. Вычислителю всё равно, что считать. Мне — нет. Каждое «нет ответа» он печатает на ленте одной дыркой. Я иногда сижу ночью и считаю эти дырки руками. Однажды машина сорок раз повторила одно имя: на него сорок раз ответили разные голоса. Я проверил реле. Реле исправны. Я не стал чинить то, что не сломано." },
    20: { t: "Стражи узла", a: "Дарья Ковригина, связистка радиоузла", x: "У шлюза узла стоит одна из двух машин, сменами. Голос надзора — корпус в репродукторах, как ёж: командует машинами, глушит «Эхо» перекличкой в упор и зовёт наладчиков; бей, когда он набирает воздух перед именем, в этот миг поле молчит. Хранитель картотеки — монтажная машина: решётки в три ряда, турели у каждого ящика, поле над соседями, уборщики на подмогу; ионы и позитроны режут её сварку. Ключ-карту я спрятала от обоих на этом этаже — в шкафу с лентами, за катушками. Найдёте — не путайте ленты." }
  },
  zero: {
    1: { t: "Кольца", a: "Мирон Кречетов, старшина кордона", x: "Нулевой кордон — не одна стена, а кольца, одно ниже другого. Первое замкнули в первый же день Тихой: сварили ворота из бурильных труб первых, засов — из трубы. Потом добавляли кольца, пока не кончились трубы. За каждым кольцом тише, чем за прежним, и тишина там старше. Постовые нулевого кордона меняются чаще всех: долго здесь не выдерживает никто. У ворот каждого кольца висит ключ на гвозде. Его не прячут: открывать всё равно запрещено. Снять запрет может только тот, кто объявил карантин. Или Академик." },
    8: { t: "Брезентовый санпост", a: "Санитарка санпоста", x: "Наш санпост сшит из брезента палаток первых. Брезент старый, побелел, но держит: его штопали трижды. Аптечный сундук с выжженной надписью «Берг» тоже оттуда, из лагеря первых. Внутри — бинты, склянки и ампулы отложенного заживления: колют до боя, действует через две минуты. Иногда снизу, старыми штольнями в обход колец, поднимаются люди. Говорят, что жили у старых выработок и что Тихая там не берёт: там считают вслух с самого начала. Мы их моем, кормим, записываем. Ни один не захотел остаться. Все возвращаются вниз." },
    20: { t: "Стражи колец нулевого кордона", a: "Мирон Кречетов, старшина кордона", x: "У шлюза этого кольца сменами стоят трое, и все трое старше кордона. Страж нулевого кордона — первый кордонный автомат, из бурильных труб: поле над соседями, иглы по площади, кордоны на подмогу; ионами. Нулевой больной — Ефрем Глотов, первый в списке Тихой: «Эхо» рядом с ним слепнет, нервы горят, затихшие идут на его зов; громким звуком и жаром. Первый глушитель — машина протокола тишины, слышит шаги через весь ярус, бьёт противозвуком; громкий звук перегружает раструб. Ключ-карта у стража при себе. Отзовись у ворот." }
  }
} });

/* ── ЗАПИСКИ ПЕРСОНАЛА: половина — полезные, половина — живые ── */
D({ staff: [
  { t: "Таблица громкого", a: "Мирон Кречетов, старшина кордона", x: "Выучить на память. Всё, что живёт тишиной, — затихшие, поглотители, глушец, глухие крысы — боится громкого звука и жара: ревун, колокол, паровое копьё, прожигатель. Машины кордона — автоматы, дроны, надзиратели, глушители — боятся ионов, ЭМИ и тока: разрядник наладчика их немеет. Живое без брони берут иглы и хлорка. Слухачей не пугай тишиной — пугай звуком: для них он пытка." },
  { t: "Терминал поста", a: "Постовой кордона", x: "Заставные турели отключаются с терминала безопасности этажа, с него же снимается блокировка дверей. Ищите его среди терминалов этажа: у него свой писк. После этого наладчики кордона сами выходят чинить турели — их так собрали, приказа им не нужно. Встречайте наладчиков первыми: они хлипкие, а без них кордон не чинится. Перехваченные турели бьют по своим, пока надзор не вернёт их контрвзломом." },
  { t: "Как стучать тихим", a: "Квартальный счётчик", x: "Три удара, пауза, три удара — «свой». Два — «уходи». Дробь — «беда». Ладонь плашмя по стене — «здесь». Стучите по трубе или по камню, не по дереву: дерево глотает. Тихие отвечают не сразу, им надо приложить ладонь и прочесть. Если ответили тремя — проходите спокойно, вас не тронут. Если двумя — уходите тем же путём. Если дробью — у них беда, и, может быть, вам стоит помочь." },
  { t: "Глушители", a: "Евсей Глотов, главный механик кордона", x: "Глушители старого протокола я собирал упрямыми: они ходят по маршрутам и не слышат новых приказов. Их вой глушит слух «Эхо» на пару секунд. В эти секунды не стреляйте наугад: замрите и ждите, пока слух вернётся. Звонница счётчика — жилет в колокольчиках — от этого спасает. Громкое оружие перегружает раструб: после пары залпов ревуна глушитель хрипит и сбивается." },
  { t: "Сборщики", a: "Пров Кречетов, кладовщик опечатанного", x: "Сборщик медленный, но схватит — не вырвешься: ноги вязнут, как в глине. Не подпускайте вплотную, отходите и бейте издали, лучше ионами и током. Сборщики открывают двери — закрытая дверь от них не спасёт. Зато в кузове у них бывают ключи и бирки: всё, что снимают с тех, кого забирают. Отдавайте найденное мне на склад. Или не отдавайте. Я не надзор." },
  { t: "Про счётчики", a: "Скупщик опечатанного", x: "Сфера на рельсе не стреляет, а слушает. Тихий шаг она пропускает: свои, по её разумению, не топают. Топнете — объявит тревогу, и сборщики с кордоном пойдут на вас. Ответите на её «отзовитесь» — успокоится. Чужая бирка на запястье даёт минуту, когда она вас не замечает вовсе. В сумраке, где рельс обмотан войлоком, сферы глухие, и там торгую я." },
  { t: "Хлорная граната", a: "Ерофей Ряднов, старший дезинфектор", x: "Рецепт для мастерской: две порции хлорной извести, линза под колбу и конденсатор под запал. Колба лопается облаком, которое жжёт всё живое на шаг вокруг. Машинам — почти ничего, крысам и мху — конец. Бросайте далеко: облако не разбирает своих. Хлорную известь берите с баков дезинфекторов — у них её всегда с запасом." },
  { t: "Распылитель и баллоны", a: "Ерофей Ряднов, старший дезинфектор", x: "Хлорный распылитель собирается у верстака: две порции хлорной извести, три лома, конденсатор и сургучная пломба на горловину. Баллон к нему — порция извести и пломба: сургуч держит давление лучше любой резьбы. Бьёт недалеко, зато облаком — цель и всё живое рядом. Против машин бесполезен, против крысиной стаи — лучше всего." },
  { t: "Сыворотка «Отклик»", a: "Аглая Берг, санитарный врач карантина", x: "Рецепт сыворотки: порция сухого глушца, реагент и гель. Глушец в сыворотке — не яд, а противоядие: мох, побеждённый реагентом, учит кровь не бояться спор. Сыворотка снимает отравление, держит новый яд на расстоянии и возвращает силы. Колите, когда в ушах начинает звенеть тишина. Отложенное заживление — две порции глушца, два геля и реагент: действует через две минуты." },
  { t: "Бахилы и балахон", a: "Прасковья Рудая, старейшая общины перестука", x: "Записано для слышащих. Бахилы шьём из двух лоскутов войлока глухой зоны и щепоти сухого глушца между слоями: шаги в них не слышны ни машинам, ни тварям. Балахон — пять лоскутов войлока, две порции глушца и проволока на швы. В балахоне вас не услышат совсем, но и «Эхо» будет ворчать: ему в войлоке темно. Войлок берите у глушителей — им он всё равно не нужен." },
  { t: "Колокольная бронза", a: "Глашатай ГЛ-9", x: "Бронзу снимают с медных деталей старых машин, что звонили на перекличку. Из одного обломка и проволоки выходит колокольчик изолятора — бросьте, и на звон пойдёт всё, что слышит. Из двух, чипа и конденсаторов — ревун кордона. Из трёх и лома — колокол счётчика. Из четырёх, проволоки и керамики — звонница, жилет, в котором тишина не пристаёт к слуху." },
  { t: "Капсулы и койки", a: "Санитарка изолятора", x: "Капсулы восстановления стоят там, где спят и лечат: в палатах боксов, перевязочных, на террасах Слушальни, в опечатанных квартирах. «Эхо» возвращает вас в последнюю капсулу, где вы лежали. Ложитесь на каждом этаже: в карантине это не совет, а правило. Иногда в капсуле снятся чужие сны — обрывки голосов тех, кто лежал здесь до вас. Не пугайтесь. Отзовитесь им." },
  { t: "Испытания надзора", a: "Санитарный надзор", x: "Справка. Стенды испытаний стоят в шлюзах кордона, в кабинетах аудиометрии и в камерах выдержки. Испытание проходят один раз; отметку вношу в списки, премию выдаю кредитами. Проба слуха: найти по звуку тикающий жетон. Выдержка тишины: полминуты без выстрела и бега. Прорыв кордона: выстоять. Сбой дезкамеры: разомкнуть схему заряда. Сверка списка: свести счёт. Для сбоя дезкамеры нужен статус допущенного." },
  { t: "Оружие по допуску", a: "Корней Ряднов, постовой заставы", x: "Кордонная винтовка «Застава» и прожигатель «Санобработка» стреляют не у всех: спуск заблокирован, пока надзор не внесёт тебя выше. «Заставе» нужен статус допущенного, «Санобработке» — сменщика. Статус поднимают испытания и нормы смены. Норму не сдал — минус. Оружейная надзора тоже по допуску: без статуса её дверь или ящики не откроются, хоть ломом бей." },
  { t: "Ходячий автоклав", a: "Ерофей Ряднов, старший дезинфектор", x: "Если услышите, как по цеху шагает котёл на шести ногах, — это автоклав. Бьёт паром, а раненый бросается вплотную и лопается, обваривая всё вокруг. Не подпускайте его, когда он ранен: отходите, бейте издали. Холод сбивает ему давление — слышно, как пар в нём захлёбывается. Пламя ему нипочём: он сам печь." },
  { t: "Глухие крысы", a: "Пров Кречетов, кладовщик опечатанного", x: "Крысы на складе не пищат: мох-глушец забивает им глотки, и стая подкрадывается беззвучно, только шуршит. Мох с их шкур пылит и травит — после укуса уколите сыворотку или выпейте антидот. Бейте жаром и громким звуком: от ревуна стая разбегается. Если шуршит целый ворох бумаги, а бумаги нет — это не стая, это король. Уходите." },
  { t: "Список на смену", a: "Прохор Зотов, квартальный счётчик", x: "Взять: рупор, отвар Деевой для горла, мел, журнал отзывов, три колокольчика — один отдать Феде Сухову, он просил. Обойти: восьмой, девятый, третий, школу. В третьем стучать дольше, там тихие, они не сразу слышат. В конце обхода — зотовская строка. Не забыть: Матрёна просила передать Луше Рядновой, что Корней на заставе и считает. Не забыть: самому отозваться на перекличке. Вчера забыл. Надзор записал меня в Тихую на полчаса." },
  { t: "Стихи из восьмого дома", a: "Неизвестный жилец восьмого дома", x: "Нас опечатали бумагой, сургучом и тишиной. Мы стали тихой ватагой за запертой стеной. Но каждый час, как по приказу, звучит из-за дверей: «Здесь, здесь», — по сорок раз, то громче, то слабей. А если кто-то не ответит, ответит за него сосед. И всё, что нас ещё на свете держит, — это стук в ответ." },
  { t: "Ссора на кухне", a: "Матрёна Деева, кормилица восьмого дома", x: "Записываю для надзора, раз он всё записывает. Евдоха из девятого дома сказала, что я пою фальшиво и что от моего пения её внуки не выздоравливают, а глохнут. Я сказала, что от её молчания глохнут быстрее. Она сказала, что молчание — по протоколу. Я сказала, что протокол отменили. Она сказала, что не слышала. Я сказала: вот видишь. Помирились на том, что теперь поём вдвоём. Она — фальшивее." },
  { t: "Записка в окошко", a: "Лукерья Ряднова, восьмой дом", x: "Корнею на заставу, через Матрёну. Корней, я отвечаю каждый час. Громко, как ты велел, — соседи жалуются. У меня всё хорошо: окошко, суп, Матрёнины песни. Только голоса стали странные: твой голос в письмах я слышу, а голос Матрёны — как будто из-под воды. Наверное, вода в ушах после хлорного душа. Не беспокойся. Я стучу тебе каждый вечер по трубе, три раза. Ты не услышишь, но я стучу." },
  { t: "Отвар для горла", a: "Матрёна Деева, кормилица восьмого дома", x: "Для счётчиков, что срывают голос. Горсть сушёного грибного чая, ложка мёда с нижних пасек, если есть, если нет — ложка сахара из пайка. Кипяток. Настоять, пока остынет до тёплого. Пить мелкими глотками между кругами. Не кричать сразу после: сначала погудеть с закрытым ртом, как тихие, потом говорить. Прохор пьёт по три кружки за обход и всё равно хрипит. Но хрипит громко." },
  { t: "Долги постового", a: "Корней Ряднов, постовой заставы", x: "Должен Мирону: смену в ночь — две, сухарей — горсть. Должен Ерофею: бутылку раствора для рук, он мне свою отдал. Должен Прохору: голос. Он сорвал свой, выкрикивая Лушу, когда я не мог отойти с поста. Должен Луше: всё. Должен надзору: отзываться каждый час. Это единственный долг, который я плачу без опозданий." },
  { t: "Анекдот кордонных", a: "Постовой кордона", x: "Приходит тихий на заставу и стучит в шлагбаум три раза. Постовой ему: «Отзовитесь!» Тихий стучит три раза. Постовой: «Голосом!» Тихий стучит громче. Постовой: «Не положено!» Тихий достаёт мел и пишет на шлагбауме: «Я здесь. А ты?» Постовой думал до конца смены. Потом пропустил. Мирон ругался, но в устав вписал." },
  { t: "Сон санитарки", a: "Санитарка изолятора", x: "Мне снилось, что Тихая кончилась. Что я иду по палате боксов, звоню в каждый звонок, и мне отвечают голосами — все сразу, как в праздник. Стёкла убирают, ленты срывают, сургуч крошится под ногами, как сухари. А в конце палаты стоит человек в старом пальто и говорит: «Я Академик. Снимаю карантин». Я проснулась от звонка в девятом боксе. Девятый звонит. Значит, слышит. Значит, и так хорошо." },
  { t: "Письмо Академику", a: "Ксюша Деева, семь лет", x: "Дорогой Академик. Бабушка Матрёна говорит, что карантин может снять только тот, кто его объявил, или вы. Тот, кто объявил, молчит. Значит, вы. Пожалуйста, спускайтесь быстрее. У нас опечатана школа, и я не знаю, кто из класса здоров. Я считаю их вслух каждый вечер по журналу, который нашла у будки дяди Прохора. Отвечают не все. Если вы спуститесь, я покажу вам нашу считалку. Ваша Ксюша." },
  { t: "Расписание стука", a: "Община перестука", x: "Записано на стене зала, для своих и для слышащих. Утром, после первой переклички надзора, — стук всем кварталам: «здесь». Днём — трубная почта, по очереди, по табличке. Вечером — колыбельная перестука детям: ладонью по груди. Ночью — тишина, но не глухая: каждый, кто не спит, держит ладонь на трубе и слушает, не стучит ли кто «беда». Стучит — встаём все." },
  { t: "Жалоба на будильники", a: "Сторож склада опечатанного", x: "Начальнику склада. Прошу разрешения остановить будильники в узлах. Их на складе сто двенадцать, и каждый звонит в своё время, а некоторые — в одно. В три часа ночи звенят одиннадцать сразу, и сборщики сбиваются со счёта. Ответ кладовщика Кречетова на обороте: «Не останавливать. Их заводили люди, чтобы знать, что ещё слышат звонок. Пусть звонят за них»." },
  { t: "Песня дезинфекторов", a: "Ерофей Ряднов, старший дезинфектор", x: "Поём в цехе, чтобы не затихнуть под шипение форсунок. «Хлорка в глаза, известь в рукав, мойся, квартал, ты опять не прав. Узел — в печь, бельё — в чан, кто не поёт — тот в дезкарман». Что такое дезкарман, никто не знает. Придумал Ерофей Ряднов, то есть я, в третью ночную смену. С тех пор поём. Работа идёт быстрее, Тихая к цеху не подходит." },
  { t: "Аудиометрия: замечание", a: "Аудиометристка кордона", x: "В журнал аудиометрии, для надзора. Прибор исправен, проверен дважды. Неучтённый сверху слышит тоны ниже последнего деления. Я дала ему самый тихий тон, какой у меня есть, — он сказал: «Справа, чуть выше середины». Это правда. Потом сказал, что слышит, как у меня в кармане тикают часы. Это тоже правда. Прошу выдать мне прибор с делениями пониже или выдать ему мой. Ему нужнее." },
  { t: "Про гончих", a: "Савелий Деев, смотритель Слушальни", x: "Гончие надзора были хорошими псами: искали больных по запаху, лаяли у дверей, где кто-то затих. Тихая отняла у них лай. Теперь они охотятся молча, сворой, и слышно их только по дыханию, совсем рядом. Без вожака гончие теряются — если услышите седого пса величиной с телёнка, бейте его первым. А я всё равно оставляю им у кордона миску. Они приходят. Едят молча. Хвостами виляют." },
  { t: "Последний урок", a: "Учительница опечатанной школы", x: "Классный журнал, на обороте обложки. В последний день перед опечатыванием мы учили считалку первых. Двадцать два ученика. На слове «здесь» двое не ответили: Ваня и Устя смотрели на меня и не слышали. Я подумала, что они шалят. Потом пришли санитары. Школу опечатали вместе с нами. Мы считали вслух трое суток, по очереди, чтобы никто не уснул в тишине. На четвёртые нас выпустили: кто слышал — по домам, кто нет — в Слушальню. Ваня и Устя вернулись оттуда и отвечают стуком." },
  { t: "Звонок свиданий", a: "Варвара Мокеева", x: "В переговорной у стекла есть отдельный звонок — звонок свиданий. Санитарка говорит: уходя, позвони, и больной поймёт, что ты ушла, а не пропала. Я звоню каждый раз. Миша прижимает трубку к груди и кивает. Вчера он позвонил в ответ сам — из бокса, своим звонком. Санитарка записала: «отзыв». Я записала у себя: «сказал до свидания». Сестра говорит, что это одно и то же." }
] });

